  ('4b9c8803-e5bd-5628-a67e-5a74f9c8dd07', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'matriz_documentos_analisados', 'VI — Matriz dos Documentos Analisados', 6, false, null, 'Foram analisados {{total_documentos}} documentos, totalizando {{total_paginas}} páginas, compreendendo {{categorias_principais}}, com suficiência documental global classificada como {{suficiencia_documental_global}}.'),
