  ('8f00458f-bede-5ca6-89af-a139e5fa8b67', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'contrato_documentacao_prestacao_servicos', 'VIII — Contrato / Documentação da Prestação de Serviços', 8, false, null, null),
  ('bcef3eee-1128-5fcc-80f2-422d09570157', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'reconstrucao_cronologica_assistencia', 'IX — Reconstrução Cronológica da Assistência', 9, false, null, 'Cadastrar cada evento de forma individual. O sistema permite ordenação automática por data/hora e gera narrativa cronológica a partir dos eventos cadastrados.'),
  ('c97f1bbe-d722-5b45-ba8e-fa130db630d8', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'estado_anterior_fatores_risco', 'X — Estado Anterior e Fatores de Risco', 10, false, null, null),
