  ('15252665-17e6-56fb-b1be-3e7973dc5301', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'exame_medico_pericial_direto', 'XII — Exame Médico-Pericial Direto — quando aplicável', 12, true, '{"todas": [{"campo_codigo": "situacao_vital", "valores_gatilho": ["vivo"]}, {"campo_codigo": "modalidade_pericia", "valores_gatilho": ["direta", "mista", "outra_modalidade_admitida"]}]}'::jsonb, null),
