  ('136b0fc3-3f37-5b9f-9382-8346ae09eb13', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'auditoria_prontuario_qualidade_documental', 'XV — Auditoria do Prontuário e Qualidade Documental', 15, false, null, null),
  ('1bd7b503-ae45-5f56-9875-25dc0c849ee7', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'analise_condutas_medicas_questionadas', 'XVI — Análise das Condutas Médicas Questionadas', 16, false, null, 'Cadastrar uma matriz para cada conduta, profissional ou momento decisório questionado.'),
  ('f539debe-3f54-5041-ab58-3f2dee0fef16', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'analise_prestacao_medico_hospitalar', 'XVII — Análise da Prestação Médico-Hospitalar', 17, false, null, null),
  ('3d99aefc-1290-5d04-b394-7f030fa219b9', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'confronto_padrao_tecnico_literatura', 'XVIII — Confronto com o Padrão Técnico e Literatura', 18, false, null, null),
  ('b10b32d8-c9e5-56de-adc2-47342ae34d58', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'caracterizacao_desfecho_dano', 'XIX — Caracterização do Desfecho / Dano', 19, false, null, null),
  ('26db7016-dd3c-575c-9de8-028a1d3e9eb1', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'nexo_causal_concausalidade', 'XX — Nexo Causal e Concausalidade', 20, false, null, null),
  ('98d679ca-f7c7-5026-95d5-5d6544965105', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'matriz_agente_reu_prestador', 'XXI — Matriz por Agente / Réu / Prestador', 21, false, null, null),
  ('e3f7e1ec-918d-5d2b-a547-df3704947483', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'tres_camadas_conclusao', 'XXII — Três Camadas Obrigatórias da Conclusão', 22, false, null, 'TRAVA CENTRAL: inadequação documental ou técnica não deve gerar automaticamente nexo causal. Da mesma forma, resultado adverso ou complicação não deve gerar automaticamente inadequação assistencial.'),
  ('ba332ded-e910-57e3-aa0f-4a0d85130236', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'discussao_medico_legal', 'XXIII — Discussão Médico-Legal', 23, false, null, 'O(a) periciando(a) apresentava, previamente ao evento assistencial discutido, {{descricao_estado_anterior}}. Do ponto de vista clínico, o quadro correspondeu a {{queixa_diagnostico_inicial}}. No confronto com o padrão técnico aplicável ao contexto, a classificação global foi de {{classificacao_global_confronto}}. O desfecho consistiu em {{classificacao_medico_pericial_desfecho}}, caracterizado objetivamente por {{dano_objetivamente_demonstrado}}, com sequelas atuais de {{sequelas_atuais}}. Consideradas a temporalidade, a plausibilidade fisiopatológica, o estado anterior e as causas alternativas, a relação causal é classificada como {{nexo_causal_resultado}}. As limitações documentais relevantes são {{impacto_fragilidades_documentais_sobre_analise}}.'),
  ('9cf2be03-f9f3-55e6-ad66-0d74b6c6f0fa', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'conclusao_medico_pericial', 'XXIV — Conclusão Médico-Pericial', 24, false, null, null),
  ('4911ddfb-6ae9-5073-9fdb-90c55e444781', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'respostas_quesitos', 'XXV — Respostas aos Quesitos', 25, false, null, null),
  ('49ed6b95-2eb7-5068-a187-c535debe3ab8', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'quadro_resumo_juizo', 'XXVII — Quadro-Resumo para o Juízo', 26, false, null, 'Modalidade da perícia: {{modalidade_pericia}}. Situação do periciando: {{situacao_vital}}. Documentação: {{suficiencia_documental_global}}. TCLE: {{tcle_status}}. Contrato de prestação: {{contrato_apresentado}}. Adequação técnico-assistencial: {{camada_adequacao_tecnico_assistencial}}. Dano: {{camada_existencia_dano}}. Nexo: {{camada_relacao_causal}}. Estado anterior/concausas: {{concausas_causas_alternativas}}. Prognóstico: {{prognostico}}.'),
  ('09522b45-0c2c-54d5-99a6-207bf21591ed', '0d803fa0-a82c-5dd2-aa29-2ca93b343892', 'encerramento', 'XXVIII — Encerramento', 27, false, null, 'O presente laudo expressa o entendimento técnico deste(a) Médico(a) Perito(a) Judicial, fundamentado nos elementos disponibilizados nos autos, no exame pericial quando realizado, na reconstrução documental da assistência e nos referenciais técnico-científicos pertinentes ao objeto da demanda. As conclusões restringem-se à matéria médico-pericial, cabendo ao Juízo a valoração jurídica dos fatos, a definição de culpa, responsabilidade civil, obrigação de indenizar e demais consequências jurídicas. Permanecendo à disposição para eventuais esclarecimentos. {{cidade_uf_assinatura}}, {{data_assinatura}}. Dr(a). {{nome_perito}}, Médico(a) Perito(a) Judicial, CRM/{{crm_uf}}, RQE nº {{rqe}}, se houver. Documento assinado eletronicamente.');
