  ('2ad09bf2-1cd1-5792-88b1-432173811c7d', '9cf2be03-f9f3-55e6-ad66-0d74b6c6f0fa', null, 'conclusao_modelo_automatico', 'Modelo automático de conclusão', 'selecao_unica', 1, false, true, '[{"codigo": "inadequacao_com_nexo", "rotulo": "Inadequação com nexo", "texto_automatico": "Foram identificadas divergências entre a assistência documentada e o padrão técnico aplicável ao contexto clínico, especificamente quanto a {{descricao_objetiva_inadequacao_falha}}. Tais inadequações apresentam {{nexo_causal_resultado}} com o dano {{dano_objetivamente_demonstrado}}, pelos fundamentos médico-periciais expostos."}, {"codigo": "inadequacao_sem_nexo_demonstrado", "rotulo": "Inadequação sem nexo demonstrado", "texto_automatico": "Foram identificadas inadequações técnico-assistenciais/documentais quanto a {{descricao_objetiva_inadequacao_falha}}; contudo, os elementos disponíveis não demonstram relação causal suficiente entre tais inadequações e o dano {{dano_objetivamente_demonstrado}}."}, {"codigo": "complicacao_sem_inadequacao_demonstrada", "rotulo": "Complicação sem inadequação demonstrada", "texto_automatico": "O desfecho adverso constatado mostra-se compatível com complicação reconhecida de {{queixa_diagnostico_inicial}}, não tendo sido demonstrada, nos elementos analisados, inadequação técnico-assistencial causalmente relacionada ao dano."}, {"codigo": "insuficiencia_documental", "rotulo": "Insuficiência documental", "texto_automatico": "A documentação disponibilizada não permite reconstrução suficientemente segura da assistência prestada, considerando a classificação documental de {{classificacao_situacao_documental}}, impossibilitando conclusão técnico-pericial definitiva quanto à adequação da conduta e/ou sua relação causal com o desfecho."}]'::jsonb, null, false, null, true),
